<script setup lang="ts">import{ref}from'vue';import{useRouter}from'vue-router';import{useAuth}from'../stores/auth';import{Eye,EyeOff,Hexagon}from'lucide-vue-next';const username=ref(''),password=ref(''),show=ref(false),busy=ref(false),error=ref('');const auth=useAuth(),router=useRouter();async function submit(){busy.value=true;error.value='';try{await auth.login(username.value,password.value);router.push('/')}catch(e:any){error.value=e.response?.data?.detail||'Não foi possível entrar.'}finally{busy.value=false}}</script>
<template><main class="grid min-h-screen place-items-center bg-[radial-gradient(circle_at_top,#dff4e8,transparent_45%)] p-5"><section class="w-full max-w-md"><div class="mb-8 text-center"><div class="mx-auto mb-4 grid h-20 w-20 place-items-center rounded-3xl bg-forest text-amber shadow-xl"><Hexagon :size="46"/></div><h1 class="text-4xl font-black text-forest">BPS</h1><p class="mt-1 text-slate-500">Bee Protection System</p></div><form class="card space-y-4" @submit.prevent="submit"><div><label class="label">Usuário</label><input v-model="username" class="field" autocomplete="username" required></div><div><label class="label">Senha</label><div class="relative"><input v-model="password" class="field pr-12" :type="show?'text':'password'" autocomplete="current-password" required minlength="8"><button type="button" class="absolute right-3 top-3 text-slate-500" @click="show=!show" :aria-label="show?'Ocultar senha':'Mostrar senha'"><EyeOff v-if="show"/><Eye v-else/></button></div></div><p v-if="error" role="alert" class="rounded-xl bg-red-50 p-3 text-sm text-red-700">{{error}}</p><button class="btn w-full" :disabled="busy">{{busy?'Entrando…':'Entrar'}}</button></form></section></main></template>
